import{_ as r,o as a,c as t,ad as o}from"./chunks/framework.BJi0JF_z.js";const u=JSON.parse('{"title":"Awesome Vibe Coding","description":"","frontmatter":{},"headers":[],"relativePath":"topics/vibe-coding.md","filePath":"topics/vibe-coding.md"}'),i={name:"topics/vibe-coding.md"};function l(n,e,s,h,d,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="awesome-vibe-coding" tabindex="-1">Awesome Vibe Coding <a href="https://awesome.re" target="_blank" rel="noreferrer"><img src="https://awesome.re/badge.svg" alt="Awesome"></a> <a class="header-anchor" href="#awesome-vibe-coding" aria-label="Permalink to &quot;Awesome Vibe Coding [![Awesome](https://awesome.re/badge.svg)](https://awesome.re)&quot;">​</a></h1><blockquote><p>A hand-picked collection of tools and references for building software with the help of AI—through prompts, iterations, and exploration.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This list focuses on tools and workflows where AI plays a central role in the development process. Instead of traditional coding, this approach emphasizes describing ideas, iterating quickly, and trusting the process—even when you’re not sure where it’s headed.</p><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#what-is">What is</a></li><li><a href="#web-based-builders">Web-Based Builders</a></li><li><a href="#editors-and-ides">Editors and IDEs</a></li><li><a href="#mobile-tools">Mobile Tools</a></li><li><a href="#extensions--plugins">Extensions &amp; Plugins</a></li><li><a href="#desktop--local-apps">Desktop &amp; Local Apps</a></li><li><a href="#cli-tools">CLI Tools</a></li><li><a href="#ai-driven-task-management">AI-Driven Task Management</a></li><li><a href="#project-documentation">Project Documentation</a></li><li><a href="#articles--updates">Articles &amp; Updates</a></li><li><a href="#contributing">Contributing</a></li></ul><hr><h2 id="what-is" tabindex="-1">What is <a class="header-anchor" href="#what-is" aria-label="Permalink to &quot;What is&quot;">​</a></h2><ul><li><a href="https://x.com/karpathy/status/1886192184808149383" target="_blank" rel="noreferrer">Karpathy on the &quot;vibe coding&quot; mindset</a> — Not traditional coding. More like shaping software through language and intuition.</li><li><a href="https://github.com/automata/aicodeguide" target="_blank" rel="noreferrer">AI Coding Guide by Automata</a> — A structured starting point for newcomers using AI-first development approaches.</li></ul><hr><h2 id="web-based-builders" tabindex="-1">Web-Based Builders <a class="header-anchor" href="#web-based-builders" aria-label="Permalink to &quot;Web-Based Builders&quot;">​</a></h2><ul><li><a href="https://bolt.new/" target="_blank" rel="noreferrer">Bolt.new</a> — Rapidly prototype and launch web and mobile apps by prompting.</li><li><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Lovable</a> — Full-stack applications from simple ideas.</li><li><a href="https://v0.dev/chat" target="_blank" rel="noreferrer">Vercel’s v0</a> — Helps design and implement UIs from natural language.</li><li><a href="https://capacity.so/" target="_blank" rel="noreferrer">Capacity</a> — Create production-ready web apps in minutes.</li><li><a href="https://chai.new" target="_blank" rel="noreferrer">CHAI.new</a> — Code and deploy AI agents with prompts.</li><li><a href="https://replit.com/" target="_blank" rel="noreferrer">Replit</a> — Type what you want and let the AI construct it.</li><li><a href="https://www.create.xyz/" target="_blank" rel="noreferrer">Create</a> — Converts text prompts into usable tools or websites.</li><li><a href="https://www.trickle.so/" target="_blank" rel="noreferrer">Trickle</a> — AI-based visual builder for websites and apps.</li><li><a href="https://www.tempo.new/" target="_blank" rel="noreferrer">Tempo</a> — Build React projects much faster through AI assistance.</li><li><a href="https://softgen.ai/" target="_blank" rel="noreferrer">Softgen</a> — Describe a concept and generate a working full-stack app.</li><li><a href="https://getlazy.ai/" target="_blank" rel="noreferrer">Lazy AI</a> — Enterprise-focused prompt-based application builder.</li><li><a href="https://www.heyboss.xyz/" target="_blank" rel="noreferrer">HeyBoss</a> — Generate functional websites quickly.</li><li><a href="https://getcreatr.com/" target="_blank" rel="noreferrer">Creatr</a> — Build landing pages and simple apps instantly.</li><li><a href="https://rork.app/" target="_blank" rel="noreferrer">Rork</a> — A tool focused on generating mobile apps.</li><li><a href="https://studio.firebase.google.com/" target="_blank" rel="noreferrer">Firebase Studio</a> — Google&#39;s take on agent-driven full-stack development.</li><li><a href="https://www.napkins.dev/" target="_blank" rel="noreferrer">Napkins</a> — Converts mockups or screenshots into working code.</li><li><a href="https://heroui.chat/" target="_blank" rel="noreferrer">HeroUI Chat</a> — Build interfaces without design expertise.</li><li><a href="https://www.rocket.new/" target="_blank" rel="noreferrer">Rocket.new</a> — Low-code experience for shipping apps.</li></ul><hr><h2 id="editors-and-ides" tabindex="-1">Editors and IDEs <a class="header-anchor" href="#editors-and-ides" aria-label="Permalink to &quot;Editors and IDEs&quot;">​</a></h2><ul><li><a href="https://codeium.com/windsurf" target="_blank" rel="noreferrer">Windsurf</a> — AI-focused development environment by Codeium.</li><li><a href="https://www.cursor.com/" target="_blank" rel="noreferrer">Cursor</a> — One of the most advanced AI-first code editors.</li><li><a href="https://zed.dev/" target="_blank" rel="noreferrer">Zed</a> — Built for real-time team collaboration with AI assistance.</li><li><a href="https://kiro.dev" target="_blank" rel="noreferrer">Amazon Kiro</a> — An AI-powered IDE from prototype to production.</li></ul><hr><h2 id="mobile-tools" tabindex="-1">Mobile Tools <a class="header-anchor" href="#mobile-tools" aria-label="Permalink to &quot;Mobile Tools&quot;">​</a></h2><ul><li><a href="https://www.vibecodeapp.com/" target="_blank" rel="noreferrer">VibeCode</a> — A mobile-first app creator powered by AI.</li></ul><hr><h2 id="extensions-plugins" tabindex="-1">Extensions &amp; Plugins <a class="header-anchor" href="#extensions-plugins" aria-label="Permalink to &quot;Extensions &amp; Plugins&quot;">​</a></h2><ul><li><a href="https://cline.bot/" target="_blank" rel="noreferrer">Cline</a> — Connects to your CLI and editor, interprets natural commands.</li><li><a href="https://github.com/RooVetGit/Roo-Code" target="_blank" rel="noreferrer">Roo Code</a> — An enhanced version of Cline.</li><li><a href="https://github.com/yetone/avante.nvim" target="_blank" rel="noreferrer">avante.nvim</a> — Neovim integration modeled after Cursor’s AI features.</li><li><a href="https://github.com/backnotprop/prompt-tower" target="_blank" rel="noreferrer">Prompt Tower</a> — A prompt creation interface supporting complex code blocks.</li><li><a href="https://www.augmentcode.com/" target="_blank" rel="noreferrer">Augment Code</a> — Tailored for navigating and working with large repositories.</li><li><a href="https://github.com/continuedev/continue" target="_blank" rel="noreferrer">Continue</a> — Build your own in-editor AI agents using plugins and rules.</li><li><a href="https://github.com/features/copilot" target="_blank" rel="noreferrer">GitHub Copilot</a> — Integrated assistant offering code suggestions, chats, and context-aware actions.</li><li><a href="https://aws.amazon.com/q/developer" target="_blank" rel="noreferrer">Amazon Q</a> — AWS’s generative AI solution for developers.</li><li><a href="https://www.superdesign.dev/" target="_blank" rel="noreferrer">Superdesign</a> — AI design agent for fast UI iterations.</li></ul><hr><h2 id="desktop-local-apps" tabindex="-1">Desktop &amp; Local Apps <a class="header-anchor" href="#desktop-local-apps" aria-label="Permalink to &quot;Desktop &amp; Local Apps&quot;">​</a></h2><ul><li><a href="https://www.dyad.sh/" target="_blank" rel="noreferrer">Dyad</a> — A lightweight, local platform for creating AI-driven apps without depending on the cloud.</li></ul><hr><h2 id="cli-tools" tabindex="-1">CLI Tools <a class="header-anchor" href="#cli-tools" aria-label="Permalink to &quot;CLI Tools&quot;">​</a></h2><ul><li><a href="https://github.com/anthropics/claude-code" target="_blank" rel="noreferrer">claude-code</a> — Works across codebases, provides explanations, automates tasks.</li><li><a href="https://aider.chat/" target="_blank" rel="noreferrer">aider</a> — Code side-by-side with AI from your terminal.</li><li><a href="https://block.github.io/goose/" target="_blank" rel="noreferrer">Goose</a> — Local agent framework compatible with multiple models.</li><li><a href="https://github.com/drivecore/mycoder" target="_blank" rel="noreferrer">MyCoder.ai</a> — Modular agent with GitHub integration.</li><li><a href="https://github.com/ai-christianson/RA.Aid" target="_blank" rel="noreferrer">RA.Aid</a> — Task-based AI built with LangGraph.</li><li><a href="https://github.com/maynetee/codeselect" target="_blank" rel="noreferrer">CodeSelect</a> — Sends structured source context to LLMs.</li><li><a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">OpenAI Codex CLI</a> — Experimental terminal assistant.</li><li><a href="https://github.com/google-gemini/gemini-cli" target="_blank" rel="noreferrer">Gemini CLI</a> — Terminal assistant built around Google Gemini.</li></ul><hr><h2 id="ai-driven-task-management" tabindex="-1">AI-Driven Task Management <a class="header-anchor" href="#ai-driven-task-management" aria-label="Permalink to &quot;AI-Driven Task Management&quot;">​</a></h2><ul><li><a href="https://docs.roocode.com/features/boomerang-tasks" target="_blank" rel="noreferrer">Boomerang Tasks</a> — Automatically turns big ideas into task queues.</li><li><a href="https://github.com/eyaltoledano/claude-task-master" target="_blank" rel="noreferrer">Claude Task Master</a> — Compatible with popular AI IDEs, breaks down work into subtasks.</li></ul><hr><h2 id="project-documentation" tabindex="-1">Project Documentation <a class="header-anchor" href="#project-documentation" aria-label="Permalink to &quot;Project Documentation&quot;">​</a></h2><ul><li><a href="https://www.codeguide.dev/" target="_blank" rel="noreferrer">CodeGuide</a> — Tool that builds documentation for AI-built projects.</li></ul><hr><h2 id="articles-updates" tabindex="-1">Articles &amp; Updates <a class="header-anchor" href="#articles-updates" aria-label="Permalink to &quot;Articles &amp; Updates&quot;">​</a></h2><ul><li><a href="https://addyo.substack.com/p/the-prompt-engineering-playbook-for" target="_blank" rel="noreferrer">Prompt Engineering for Developers</a></li><li><a href="https://theconversation.com/what-is-vibe-coding-a-computer-scientist-explains-what-it-means-to-have-ai-write-computer-code-and-what-risks-that-can-entail-257172" target="_blank" rel="noreferrer">What Vibe Coding Actually Means</a></li><li><a href="https://pmbanugo.me/blog/peer-programming-with-llms" target="_blank" rel="noreferrer">LLM Pair Programming</a></li><li><a href="https://www.thewayofcode.com/" target="_blank" rel="noreferrer">The Way of Code</a></li><li><a href="https://www.linkedin.com/pulse/state-vibe-coding-tools-may-2025-nufar-gaspar-x1znf" target="_blank" rel="noreferrer">2025 Tooling Overview on LinkedIn</a></li><li><a href="https://karpathy.bearblog.dev/vibe-coding-menugen/" target="_blank" rel="noreferrer">Karpathy on Menus and Vibes</a></li><li><a href="https://www.youtube.com/watch?v=Tw18-4U7mts" target="_blank" rel="noreferrer">Fireship: Mindset Video</a></li><li><a href="https://arstechnica.com/ai/2025/03/is-vibe-coding-with-ai-gnarly-or-reckless-maybe-some-of-both/" target="_blank" rel="noreferrer">Ars Technica on AI Development Futures</a></li><li><a href="https://thenewstack.io/vibe-coding-where-everyone-can-speak-computer-programming/" target="_blank" rel="noreferrer">The New Stack – Everyone Can Program</a></li><li><a href="https://www.nytimes.com/2025/02/27/technology/personaltech/vibecoding-ai-software-programming.html" target="_blank" rel="noreferrer">NYTimes: Personal Vibe Coding Experience</a></li><li><a href="https://www.reddit.com/r/vibecoding/" target="_blank" rel="noreferrer">Reddit: /r/vibecoding</a></li><li><a href="https://www.reddit.com/r/ChatGPTCoding/" target="_blank" rel="noreferrer">Reddit: /r/ChatGPTCoding</a></li></ul>',36)])])}const f=r(i,[["render",l]]);export{u as __pageData,f as default};
